/// All questions by section, set 1
Map<ActSection, List<ActQuestion>> allQuestionsSet1 = {
  ActSection.english: englishSet1,
  ActSection.math:    mathSet1,
  ActSection.reading: readingSet1,
  ActSection.science: scienceSet1,
};

/// All questions by section, set 2
Map<ActSection, List<ActQuestion>> allQuestionsSet2 = {
  ActSection.english: englishSet2,
  ActSection.math:    mathSet2,
  ActSection.reading: readingSet2,
  ActSection.science: scienceSet2,
};

/// All questions by section, set 3
Map<ActSection, List<ActQuestion>> allQuestionsSet3 = {
  ActSection.english: englishSet3,
  ActSection.math:    mathSet3,
  ActSection.reading: readingSet3,
  ActSection.science: scienceSet3,
};

/// Every question bank set currently available, keyed by set number.
/// Add new sets here as they're generated — everything else (Full Practice
/// Exam set picker, Section Practice set picker, Random Mix) reads from
/// this map so no other file needs to change when a new set is added.
final Map<int, Map<ActSection, List<ActQuestion>>> allQuestionSets = {
  1: allQuestionsSet1,
  2: allQuestionsSet2,
  3: allQuestionsSet3,
};

/// Set numbers available in the app, in display order.
List<int> get availableSetNumbers => allQuestionSets.keys.toList()..sort();

/// Get questions for a section, optionally for a specific set (defaults to
/// Set 1 so every existing call site keeps compiling/behaving unchanged).
List<ActQuestion> questionsForSection(ActSection section, {int setNumber = 1}) {
  return allQuestionSets[setNumber]?[section] ?? allQuestionsSet1[section] ?? [];
}

/// Every question from every section pooled together for a given set —
/// used by the "Random Mix" subject option (Online Challenge & WiFi
/// Challenge) so a session can pull questions across subjects instead of
/// just one.
List<ActQuestion> questionsForRandomMix({int setNumber = 1}) {
  final set = allQuestionSets[setNumber] ?? allQuestionsSet1;
  return [
    ...set[ActSection.english] ?? [],
    ...set[ActSection.math] ?? [],
    ...set[ActSection.reading] ?? [],
    ...set[ActSection.science] ?? [],
  ];
}
